package dev.chyken.assembl_ar.vision;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
public final class ReferenceCacheIndexTest {
    @Rule public TemporaryFolder temporary=new TemporaryFolder();
    private File apk(String name,String photo)throws Exception{File apk=new File(temporary.getRoot(),name);try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(apk))){out.putNextEntry(new ZipEntry("assets/references/test.jpg"));out.write(photo.getBytes(java.nio.charset.StandardCharsets.UTF_8));out.closeEntry();}return apk;}
    private ComponentReferenceSpec spec(){return ComponentReferenceSpec.builder("photo","part","Part",20,30).jpegAssetPath("references/test.jpg").build();}
    @Test public void sourceCrcAlgorithmAndConfigurationInvalidateOnlyTheirOwnCompiledEntries()throws Exception{File folder=temporary.newFolder();File apk=apk("a.apk","first");VisionConfig config=VisionConfig.defaults();ReferenceCacheIndex index=new ReferenceCacheIndex(folder,apk.getPath(),"v1");File blob=new File(folder,"one.asor");Files.write(blob.toPath(),new byte[]{1});assertFalse(index.terminal(spec(),config));index.remember(spec(),config,blob);assertTrue(index.terminal(spec(),config));assertFalse(index.terminal(spec(),VisionConfig.builder().clahe(3.0,8,8).build()));assertTrue(new ReferenceCacheIndex(folder,apk.getPath(),"v1").terminal(spec(),config));assertFalse(new ReferenceCacheIndex(folder,apk.getPath(),"v2").terminal(spec(),config));assertFalse(new ReferenceCacheIndex(folder,apk("b.apk","replacement").getPath(),"v1").terminal(spec(),config));blob.delete();assertFalse(index.terminal(spec(),config));}
    @Test public void sourceRoiAndPhysicalGeometryCannotReuseOtherCompiledGeometry()throws Exception{File folder=temporary.newFolder();ReferenceCacheIndex index=new ReferenceCacheIndex(folder,apk("a.apk","same").getPath(),"v1");File blob=new File(folder,"one.asor");Files.write(blob.toPath(),new byte[]{1});index.remember(spec(),VisionConfig.defaults(),blob);ComponentReferenceSpec changed=ComponentReferenceSpec.builder("photo","part","Part",21,30).jpegAssetPath("references/test.jpg").build();assertFalse(index.terminal(changed,VisionConfig.defaults()));}
    @Test public void rejectedSourceResumesWithoutRepeatedCompilationButNewPhotoRetries()throws Exception{File folder=temporary.newFolder();String path=apk("a.apk","bad").getPath();ReferenceCacheIndex index=new ReferenceCacheIndex(folder,path,"v1");index.skipped(spec(),VisionConfig.defaults());assertTrue(new ReferenceCacheIndex(folder,path,"v1").terminal(spec(),VisionConfig.defaults()));assertFalse(new ReferenceCacheIndex(folder,apk("b.apk","fixed").getPath(),"v1").terminal(spec(),VisionConfig.defaults()));}
    @Test public void changingAnotherPhaseRevisionDoesNotRecompileThisReference()throws Exception{
        File folder=temporary.newFolder();String path=apk("a.apk","same").getPath();
        ReferenceCacheIndex first=new ReferenceCacheIndex(folder,path,"library1:old-global-phase2-revision");
        File blob=new File(folder,"one.asor");Files.write(blob.toPath(),new byte[]{1});first.remember(spec(),VisionConfig.defaults(),blob);
        ReferenceCacheIndex changed=new ReferenceCacheIndex(folder,path,"library1:updated-global-phase2-revision");
        assertTrue(changed.terminal(spec(),VisionConfig.defaults()));
    }
}
